export function gearCharge(loan: Loan): number {
  const keyCost = REPLACEMENT_PENCE.boatKey;
  const jacketCost = REPLACEMENT_PENCE.lifejacket;
  const missingKeys = outstanding(loan, "boatKey");
  let damagedJackets = 0;
  for (const line of loan.lines) {
    if (line.kind === "lifejacket") damagedJackets += line.damaged;
  }
  // Copy of the loan with damaged jackets zeroed, so the previous rules
  // leave out their old damaged-jacket charge. The loan itself is untouched.
  const withoutDamagedJackets: Loan = {
    ...loan,
    lines: loan.lines.map((line) =>
      line.kind === "lifejacket" ? { ...line, damaged: 0 } : line
    ),
  };
  return (
    previousGearCharge(withoutDamagedJackets) -
    missingKeys * keyCost +
    (missingKeys > 0 ? keyCost : 0) +
    damagedJackets * jacketCost
  );
}

